def generate(level=1, **kwargs):
    from core.prompts.domain_function_library import FractionOps

    products = [{"left": "2.79", "right": "89.3", "sign": 1}, {"left": "-0.21", "right": "89.3", "sign": -1}]

    term_values = []
    for p in products:
        left_frac, right_frac = FractionOps.create(p["left"]), FractionOps.create(p["right"])
        prod_val = FractionOps.mul(left_frac, right_frac)
        if p["sign"] == 1:
            term_values.append(prod_val)
        else:
            term_values.append(FractionOps.negate(prod_val))

    total_sum = sum(term_values)

    question_text = "Evaluate the exact rational expression formed by the product of each pair multiplied by its sign, then summed."
    correct_answer_value = FractionOps.to_latex(total_sum) if not total_sum.is_integer() else str(int(total_sum.numerator))
    oracle_payload = products

    return {
        "question_text": question_text,
        "correct_answer": {"value": correct_answer_value},
        "oracle_payload": oracle_payload
    }
